(376,'bn','c:149a3728f43928f0d1e9192401e72c21b7a3fb1d','149a3728f43928f0d1e9192401e72c21b7a3fb1d','একটি ব্যস্ত মোড়ে একজন সাইকেল আরোহী দুর্ঘটনার শিকার হয়েছেন এবং পথচারীরা তাকে সাহায্য করছেন। অ্যাম্বুলেন্সের অনুরোধ করা হয়েছে।','meta-llama:Llama-4-Maverick-17B-128E-Instruct-FP8','2026-11-02 05:50:26','2026-11-02 05:50:26'),
